/**
 * 4.0 页面 · 3.0 页头导航高亮兼容脚本（属性修正主线 v3.1 · 精确优先）
 * 咨询与依据：phoenix-develop/docs/nav-highlight-local-vs-online.md（技术方案汇报）
 *
 * 精确优先底线（架构要求）：判断不精准宁可没有高亮，绝不出现同屏双高亮或错高亮。
 * 落地为三条硬规则：
 *   1) 分组单标——按导航结构（导航节点/本地组件/克隆容器）分组，每组至多标记
 *      DOM 顺序第一个命中项，同一菜单内的重复链接不会双亮；
 *   2) 低置信匹配默认关闭——R4 语言前缀兜底存在低概率误配，默认 off；
 *   3) P2 兜底打类严格对齐各体系原生转换（B1 顶级 li / B2 分层 li），
 *      不做整链加类，避免触发非预期样式。
 *
 * 机制：3.0 拉取页头（本地导航组件 + type1 定制页头区块）的导航高亮统一为
 * 服务端输出 data-currentindex 属性（当前项非空索引）+ 各区块 JS 自行转类。
 * 静态页头按默认首页拉取，baked 属性是首页的——本脚本在 DOMContentLoaded
 * （早于延迟加载的区块 JS）清 baked 并按当前 URL 重算命中写回属性，
 * 由区块自己的 JS 用各自类名完成打类；本地组件(sitewidget)另做 on 清理重打兜底。
 * 生效边界：collect.js 仅 4.0 站点发布时生成 + current_4_0_page_id 隐藏域校验。
 */
(function () {
    'use strict';

    var CFG = {
        scopes: ['#backstage-headArea', '#backstage-headArea-mobile'],
        attr: 'data-currentindex',
        langFallback: false,      // R4 默认关闭（精确优先）：启用前需真机验证多语言站误配率
        localWidgetSel: '.sitewidget-navigation, .sitewidget-navnew',
        localWidgetLinkSel: 'a.sitewidget-main-nav, a.sitewidget-sub-nav, a.navnew-link, '
                + 'a.navnew-sub1-link, a.navnew-sub2-link',
        navGroupSel: '[data-blocksEditor-type="phoenix_blocks_navigation"], .sitewidget-navigation, '
                + '.sitewidget-navnew, .clone_nav',
        debounceMs: 120,
        observerMaxMs: 60000,
        fallbackDelayMs: 500
    };

    function safe(fn) {
        try { fn(); } catch (e) { try { console.log(e); } catch (ignore) { } }
    }

    // 生效边界：4.0 渲染器输出该隐藏域（延迟加载场景下 DOMContentLoaded 再校验）
    function isEnabled() {
        return !!document.getElementById('current_4_0_page_id');
    }

    // ---------- URL 归一化（原生 JS，P1 可用） ----------
    function normPath(url) {
        try {
            var a = document.createElement('a');
            a.href = url || '';
            var p = a.pathname.replace(/\/+$/, '');
            p = p.replace(/\/(index|default)\.(html?|shtml|php|asp|jsp)$/i, '');
            return p;
        } catch (e) { return ''; }
    }
    function normHost(url) {
        try {
            var a = document.createElement('a');
            a.href = url || '';
            return a.hostname;
        } catch (e) { return location.hostname; }
    }
    function isHome(p) { return p === '' || p === '/'; }
    function sameHost(el) {
        var h = normHost(el.getAttribute('href'));
        return !h || h === location.hostname;
    }

    // ---------- 候选导航链接：带属性的 <a> 即服务端标记的导航链接 ----------
    function candidates(scope) {
        var out = [], nodes = scope.querySelectorAll('a[' + CFG.attr + ']');
        for (var i = 0; i < nodes.length; i++) {
            var el = nodes[i];
            var href = el.getAttribute('href');
            if (!href || /^\s*(javascript:|#|mailto:|tel:)/i.test(href)) { continue; }
            if (!sameHost(el)) { continue; }
            out.push(el);
        }
        return out;
    }

    // ---------- R1~R4 匹配：返回应命中的归一化 path（'HOME' 或 path 或 null） ----------
    function matchTarget(list, cur) {
        var i, p;
        // R2 精确匹配
        for (i = 0; i < list.length; i++) {
            if (normPath(list[i].href) === cur) { return cur; }
        }
        // R3 段前缀匹配（最长优先；首页链接不参与，避免全站命中首页）
        var best = null, bestLen = -1;
        for (i = 0; i < list.length; i++) {
            p = normPath(list[i].href);
            if (!p || isHome(p)) { continue; }
            if (cur.indexOf(p + '/') === 0 && p.length > bestLen) { best = p; bestLen = p.length; }
        }
        if (best !== null) { return best; }
        // R4 语言前缀兜底：去当前 path 首段重试 R2/R3（多语言前缀不对称场景）
        if (CFG.langFallback && /^\/[^/]+\/.+/.test(cur)) {
            var s = cur.replace(/^\/[^/]+/, '');
            for (i = 0; i < list.length; i++) {
                if (normPath(list[i].href) === s) { return s; }
            }
            best = null; bestLen = -1;
            for (i = 0; i < list.length; i++) {
                p = normPath(list[i].href);
                if (!p || isHome(p)) { continue; }
                if (s.indexOf(p + '/') === 0 && p.length > bestLen) { best = p; bestLen = p.length; }
            }
            if (best !== null) { return best; }
        }
        return null;
    }

    // ---------- 命中项属性值：父 li 在同级中的索引（模拟模板 nav_index） ----------
    // 跳过隐藏占位 li（.hide），与模板 menus 循环序对齐，避免 eq(index) 型区块偏移
    function indexValue(a) {
        var li = a.parentNode && a.parentNode.tagName === 'LI' ? a.parentNode : null;
        if (!li) { return '0'; }
        var idx = 0, n = li;
        while ((n = n.previousElementSibling)) {
            if (!n.classList.contains('hide')) { idx++; }
        }
        return String(idx);
    }

    // ---------- 兼容 IE 的 closest ----------
    function closestEl(el, sel) {
        if (el.closest) { return el.closest(sel); }
        var m = el.matches || el.msMatchesSelector;
        var cur = el;
        while (cur && cur !== document) {
            if (m && m.call(cur, sel)) { return cur; }
            cur = cur.parentElement || cur.parentNode;
        }
        return null;
    }

    // ---------- 导航结构分组（精确优先：每组至多标记一个，杜绝同屏双亮） ----------
    // 克隆结构（.clone_nav 等）与主导航各自成组——同一菜单项的不同渲染形态各自一致；
    // 同一菜单内的重复链接只标 DOM 序第一个。
    function navGroup(el) {
        var g = closestEl(el, CFG.navGroupSel);
        if (g) { return g; }
        return closestEl(el, CFG.scopes.join(',')) || document.body;
    }

    // ---------- P1：属性修正（原生 JS，幂等） ----------
    function fixAttributes() {
        for (var s = 0; s < CFG.scopes.length; s++) {
            var scope = document.querySelector(CFG.scopes[s]);
            if (!scope) { continue; }
            var list = candidates(scope);
            if (!list.length) { continue; }

            // 1) 清 baked（拉取页头按默认首页生成）
            for (var i = 0; i < list.length; i++) { list[i].setAttribute(CFG.attr, ''); }

            // 2) R1 首页规则 / R2~R3 重算（R4 默认关闭）
            var cur = normPath(location.href);
            var target = isHome(cur) ? 'HOME' : matchTarget(list, cur);
            if (target === null) { continue; }

            // 3) 分组单标：按导航结构分组，每组至多标记 DOM 序第一个命中项
            //    （精确优先底线——重复链接/歧义一律不多标）
            var groups = [], marked = [];
            for (var j = 0; j < list.length; j++) {
                var p = normPath(list[j].href);
                var hitNow = (target === 'HOME' && isHome(p)) || (target !== 'HOME' && p === target);
                if (!hitNow) { continue; }
                var g = navGroup(list[j]);
                var gi = groups.indexOf(g);
                if (gi === -1) { groups.push(g); gi = groups.length - 1; marked[gi] = false; }
                if (marked[gi]) { continue; }
                list[j].setAttribute(CFG.attr, indexValue(list[j]));
                marked[gi] = true;
            }
        }
    }

    // ---------- P2：本地组件 on 兜底（需 jQuery） ----------
    function localWidgetFallback() {
        if (!window.jQuery) { return; }
        var $ = window.jQuery;
        $(CFG.scopes.join(',')).each(function () {
            var $scope = $(this);
            // 1) 清理：scope 内全部本地组件的导航 on——与“是否有命中”解耦。
            //    （精确优先：无匹配页面也必须清掉 settings.js 按 baked 打的错误 on，
            //     否则首页高亮残留 = 错高亮，违反底线）
            var $widgets = $scope.find(CFG.localWidgetSel);
            if (!$widgets.length) { return; }
            $widgets.find('li[id^="parent_"].on, .navnew-item.on, .nav-sub1-item.on, .nav-sub2-item.on')
                    .removeClass('on');
            // 注意：不能直接拼 '.on' 到逗号选择器后（只会作用于最后一段）
            $widgets.find(CFG.localWidgetLinkSel).filter('.on').removeClass('on');

            // 2) 重打：仅本地组件内的命中项（定制区块命中链接不在此打类，
            //    其 on 可能是容器展开态等非高亮语义——避免触发非预期样式）
            var $hit = $scope.find('a[' + CFG.attr + ']').filter(function () {
                if (this.getAttribute(CFG.attr) === '') { return false; }
                return $(this).closest(CFG.localWidgetSel).length > 0;
            });
            if (!$hit.length) { return; }
            // 重打（精确优先：严格对齐各体系原生转换行为，不做整链加类）
            //   B1 原生：命中 a → 顶级 li[id^='parent_'] 加 on（comp.navigation.settings.js）
            //   B2 原生：按命中深度给所在分层 li 加 on（comp.navigation_style.settings.js）
            //   a 级 on：addMarkWithUrl 变体的 CSS 形态
            $hit.addClass('on');
            $hit.closest('li[id^="parent_"]').addClass('on');
            $hit.closest('.navnew-item, .nav-sub1-item, .nav-sub2-item').addClass('on');
            $hit.filter('.style_peise').addClass('gbBgColor0');
            $hit.closest('li[id^="parent_"], .navnew-item, .nav-sub1-item, .nav-sub2-item')
                    .filter('.style_peise').addClass('gbBgColor1');
        });
    }

    // ---------- 启动 ----------
    function runPhases() {
        if (!isEnabled()) { return; }
        safe(fixAttributes);
        setTimeout(function () { safe(localWidgetFallback); }, CFG.fallbackDelayMs);
    }
    function runFix() {
        if (!isEnabled()) { return; }
        safe(fixAttributes);
        safe(localWidgetFallback);
    }

    function boot() {
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', runPhases);
        } else {
            runPhases();
        }
        // P3：MutationObserver 兜底（静态页头场景为保险位；老浏览器忽略）
        safe(function () {
            var timer = null, startedAt = Date.now();
            var mo = new MutationObserver(function () {
                clearTimeout(timer);
                timer = setTimeout(function () {
                    runFix();
                    if (Date.now() - startedAt > CFG.observerMaxMs) { mo.disconnect(); }
                }, CFG.debounceMs);
            });
            mo.observe(document.body, { childList: true, subtree: true });
        });
    }

    safe(boot);
})();




